    en: { recipient: 'Our dear family and friends', sender: 'Nadine and Reza', occasion: 'With the blessing of our parents', title: 'Nadine & Reza', subtitle: 'Invite you to join them as they begin married life.', dateLine: 'Sunday, 12 July 2026 · Yogyakarta', greeting: 'Dear family and friends,', body: 'We would be grateful to have you with us for a small ceremony and lunch. We are keeping the day simple: a few vows, a table shared with the people we love, and time to catch up without a rush.', signoff: 'Warmly,', intro: '', appreciation: '', closing: 'Thank you for being part of our story.', signature: 'Nadine and Reza', list: ['Akad · 09:00', 'Family photographs · 10:30', 'Lunch reception · 12:00'], places: ['Pendopo Ndalem', 'Inner courtyard', 'Garden hall'] },
    idCopy: { recipient: 'Keluarga dan sahabat terkasih', sender: 'Nadine dan Reza', occasion: 'Dengan restu orang tua', title: 'Nadine & Reza', subtitle: 'Mengundang Anda mengiringi awal kehidupan pernikahan kami.', dateLine: 'Minggu, 12 Juli 2026 · Yogyakarta', greeting: 'Kepada keluarga dan sahabat,', body: 'Kami akan berbahagia jika Anda berkenan hadir dalam akad sederhana dan makan siang bersama. Hari itu kami jaga tetap hangat: beberapa janji, meja bersama orang-orang terkasih, dan waktu berbincang tanpa terburu-buru.', signoff: 'Salam hangat,', intro: '', appreciation: '', closing: 'Terima kasih telah menjadi bagian dari cerita kami.', signature: 'Nadine dan Reza', list: ['Akad · 09.00', 'Foto keluarga · 10.30', 'Resepsi makan siang · 12.00'], places: ['Pendopo Ndalem', 'Halaman dalam', 'Aula taman'] },
