    palette: { background: '#f3ead9', surface: '#fff7e8', ink: '#332719', mutedInk: '#655137', accent: '#76522e', accentInk: '#fff9ef', line: '#deceb0' }, display: 'serif-old', bodyFont: 'serif-classic', order: ['hero', 'timeline', 'gallery', 'letter', 'closing'], flowers: true,
    en: { recipient: 'Family, elders, and friends', sender: 'Intan and Bagus', occasion: 'A gathering of two families', title: 'Intan & Bagus', subtitle: 'Join us for the akad and a traditional Javanese reception.', dateLine: 'Saturday, 5 September 2026 · Surakarta', greeting: 'With respect and affection,', body: 'Our families would be honoured by your presence as we exchange vows and celebrate with the traditions that shaped us. The celebration includes a short ceremony, a family greeting, and dinner together.', signoff: 'With gratitude,', intro: '', appreciation: '', closing: 'May the evening be remembered with warmth.', signature: 'Intan and Bagus', list: ['Akad nikah · 15:30', 'Family greeting · 17:00', 'Dinner and reception · 18:30'], places: ['Pendopo utama', 'Serambi keluarga', 'Taman pendopo'] },
    idCopy: { recipient: 'Keluarga, para sesepuh, dan sahabat', sender: 'Intan dan Bagus', occasion: 'Pertemuan dua keluarga', title: 'Intan & Bagus', subtitle: 'Mohon hadir pada akad dan resepsi bernuansa Jawa.', dateLine: 'Sabtu, 5 September 2026 · Surakarta', greeting: 'Dengan hormat dan kasih,', body: 'Keluarga kami akan merasa terhormat atas kehadiran Anda saat kami mengucapkan janji dan merayakan tradisi yang membentuk diri kami. Acara meliputi akad singkat, sungkem keluarga, dan makan malam bersama.', signoff: 'Dengan rasa syukur,', intro: '', appreciation: '', closing: 'Semoga malam itu selalu dikenang dengan hangat.', signature: 'Intan dan Bagus', list: ['Akad nikah · 15.30', 'Sungkem keluarga · 17.00', 'Makan malam dan resepsi · 18.30'], places: ['Pendopo utama', 'Serambi keluarga', 'Taman pendopo'] },
