    palette: { background: '#f1eee5', surface: '#fbf9f3', ink: '#25241f', mutedInk: '#575f50', accent: '#4f5e47', accentInk: '#f7f5ee', line: '#d9d6c8' }, display: 'serif-old', bodyFont: 'serif-classic', order: ['hero', 'letter', 'timeline', 'gallery', 'closing'], flowers: true,
    en: { recipient: 'Dear family and friends', sender: 'Citra and Bram', occasion: 'With the blessing of our families', title: 'Citra & Bram', subtitle: 'Would be delighted to celebrate with you.', dateLine: 'Saturday, 10 October 2026 · Bogor', greeting: 'With joy,', body: 'We are bringing our favourite people together beneath the old rain trees. Join us for a ceremony, a long lunch, and a little time to wander through the garden. Please let us know if you have any dietary needs.', signoff: 'With affection,', intro: '', appreciation: '', closing: 'Your presence is the loveliest gift.', signature: 'Citra and Bram', list: ['Ceremony · 10:00', 'Garden lunch · 12:00', 'Music and coffee · 14:00'], places: ['Stone pavilion', 'East garden', 'Orchid house'] },
    idCopy: { recipient: 'Keluarga dan sahabat terkasih', sender: 'Citra dan Bram', occasion: 'Dengan restu keluarga', title: 'Citra & Bram', subtitle: 'Akan berbahagia merayakan bersama Anda.', dateLine: 'Sabtu, 10 Oktober 2026 · Bogor', greeting: 'Dengan sukacita,', body: 'Kami mengundang orang-orang terkasih berkumpul di bawah pohon hujan tua. Mari hadir untuk prosesi, makan siang panjang, dan waktu berjalan santai di taman. Silakan beri tahu jika ada kebutuhan menu khusus.', signoff: 'Dengan kasih,', intro: '', appreciation: '', closing: 'Kehadiran Anda adalah hadiah terindah.', signature: 'Citra dan Bram', list: ['Akad · 10.00', 'Makan siang taman · 12.00', 'Musik dan kopi · 14.00'], places: ['Pendopo batu', 'Taman timur', 'Rumah anggrek'] },
