    en: { recipient: 'The pleasure of your company is requested', sender: 'Sasha and Adrian', occasion: 'An evening reception', title: 'Sasha & Adrian', subtitle: 'A celebration of marriage and the people who made us.', dateLine: 'Friday, 4 December 2026 · Jakarta', greeting: 'Dear guest,', body: 'We invite you to join us for an evening of dinner, music, and conversation as we celebrate our marriage. The ceremony will be followed by a reception in the glass hall. Formal attire is requested.', signoff: 'With warm regards,', intro: '', appreciation: '', closing: 'We look forward to welcoming you.', signature: 'Sasha and Adrian', list: ['Guest arrival · 17:30', 'Ceremony · 18:00', 'Dinner reception · 19:30'], places: ['West entrance', 'Glass hall', 'Orchid ballroom'] },
    idCopy: { recipient: 'Dengan hormat kami mengundang kehadiran Anda', sender: 'Sasha dan Adrian', occasion: 'Resepsi malam', title: 'Sasha & Adrian', subtitle: 'Perayaan pernikahan bersama orang-orang yang berarti bagi kami.', dateLine: 'Jumat, 4 Desember 2026 · Jakarta', greeting: 'Kepada para tamu terhormat,', body: 'Kami mengundang Anda menikmati makan malam, musik, dan perbincangan dalam perayaan pernikahan kami. Prosesi akan dilanjutkan dengan resepsi di aula kaca. Busana formal.', signoff: 'Salam hangat,', intro: '', appreciation: '', closing: 'Kami menantikan kehadiran Anda.', signature: 'Sasha dan Adrian', list: ['Kedatangan tamu · 17.30', 'Prosesi · 18.00', 'Resepsi makan malam · 19.30'], places: ['Pintu barat', 'Aula kaca', 'Ballroom Anggrek'] },
