    palette: { background: '#f2eee5', surface: '#fffaf1', ink: '#312b22', mutedInk: '#665b4b', accent: '#78613d', accentInk: '#fffaf1', line: '#ded4bf' }, display: 'serif-old', bodyFont: 'sans-clean', order: ['opening', 'hero', 'gallery', 'appreciation', 'closing'],
    en: { recipient: 'Dad', sender: 'Your family', occasion: 'Your birthday · 9 October', title: 'A Birthday Made of Home', subtitle: 'We saved a place at the table for all your stories.', dateLine: 'Dinner at 18:00 · Saturday', greeting: '', body: '', signoff: '', intro: '', appreciation: 'Thank you for being the person who fixes what is broken and makes room for everyone to sit down.', closing: 'Come hungry. We made the rice you like.', signature: 'With love, from all of us', list: ['The first bicycle ride', 'The garden you planted with us', 'Every Sunday breakfast'], places: ['Lane behind our house', 'Back garden', 'Family kitchen'] },
