    id: 'farewell-last-train', category: 'special-moments', name: ['Before the Last Train', 'Sebelum Kereta Terakhir'], tagline: ['A farewell for a colleague leaving well', 'Perpisahan hangat untuk rekan yang melangkah ke tempat baru'], description: ['A generous farewell gift with a timeline of shared work, a note of gratitude, and a warm wish for the next chapter.', 'Hadiah perpisahan dengan linimasa kerja bersama, ucapan terima kasih, dan harapan hangat untuk bab berikutnya.'],
    palette: { background: '#edf1f0', surface: '#f9fbfa', ink: '#253337', mutedInk: '#536267', accent: '#426a70', accentInk: '#f8fbfa', line: '#ced9d8' }, display: 'serif-classic', bodyFont: 'sans-clean', order: ['opening', 'hero', 'timeline', 'letter', 'closing'],
    en: { recipient: 'Maya', sender: 'The studio team', occasion: 'Your last Friday with us', title: 'Before the Last Train', subtitle: 'A small record of the good work and better company.', dateLine: '31 July 2026 · Studio 4B', greeting: 'Dear Maya,', body: 'The studio will be quieter without your music, but it will be better for the way you taught us to ask one more question before calling a draft finished. Thank you for the care you gave to every project and every person.', signoff: 'We will miss you,', intro: '', appreciation: '', closing: 'May the next place make room for all the good you bring.', signature: 'Your team', list: ['The impossible Friday deadline', 'Lunch on the loading dock', 'The project we rebuilt together'], places: ['Studio 4B', 'Loading dock', 'Client room'] },
    idCopy: { recipient: 'Maya', sender: 'Tim studio', occasion: 'Jumat terakhirmu bersama kami', title: 'Sebelum Kereta Terakhir', subtitle: 'Catatan kecil tentang kerja baik dan kebersamaan yang lebih baik.', dateLine: '31 Juli 2026 · Studio 4B', greeting: 'Untuk Maya,', body: 'Studio akan lebih sunyi tanpa musikmu, tetapi akan mengingat caramu mengajari kami untuk bertanya sekali lagi sebelum menganggap draf selesai. Terima kasih atas perhatianmu pada setiap proyek dan setiap orang.', signoff: 'Kami akan merindukanmu,', intro: '', appreciation: '', closing: 'Semoga tempat berikutnya menyediakan ruang bagi semua kebaikan yang kamu bawa.', signature: 'Tim kamu', list: ['Tenggat Jumat yang terasa mustahil', 'Makan siang di area bongkar muat', 'Proyek yang kita bangun ulang bersama'], places: ['Studio 4B', 'Area bongkar muat', 'Ruang klien'] },
