    en: { recipient: 'Family and friends', sender: 'Rosa and Dani', occasion: 'A tiny guest is on the way', title: 'A Little Color in the Garden', subtitle: 'Join us to find out who is joining our family.', dateLine: 'Sunday, 13 September · 10:30', greeting: '', body: '', signoff: '', intro: 'What do you think the little one will be?', appreciation: '', closing: 'Light lunch is provided. Please RSVP to Rosa by 1 September.', signature: 'Rosa and Dani', list: ['Garden brunch', 'The reveal', 'Family photos and cake'], places: ['Back patio', 'Rose arbor', 'Shaded lawn'] },
    idCopy: { recipient: 'Keluarga dan sahabat', sender: 'Rosa dan Dani', occasion: 'Ada tamu kecil yang akan hadir', title: 'Warna Kecil di Taman', subtitle: 'Mari cari tahu siapa yang segera bergabung dengan keluarga kami.', dateLine: 'Minggu, 13 September · 10.30', greeting: '', body: '', signoff: '', intro: 'Menurutmu, siapa yang akan hadir?', appreciation: '', closing: 'Makan siang ringan tersedia. Mohon konfirmasi ke Rosa sebelum 1 September.', signature: 'Rosa dan Dani', list: ['Brunch di taman', 'Pengumuman kecil', 'Foto keluarga dan kue'], places: ['Teras belakang', 'Gerbang mawar', 'Taman rindang'] },
